using UnityEngine;

/// <summary>
/// Main game loop, stage progression, spawning, score tracking, local save data, and in-game GUI.
/// Visual assets are generated by SpriteFactory, so no imported art files are required.
/// </summary>
public class SpaceShooterGame : MonoBehaviour
{
    public enum ScreenState { MainMenu, Playing, BossFight, Paused, LevelClear, GameOver, Victory }

    public static SpaceShooterGame Instance { get; private set; }

    public PlayerController Player { get; private set; }
    public ScreenState CurrentState { get; private set; } = ScreenState.MainMenu;
    public bool IsGameplayActive => CurrentState == ScreenState.Playing || CurrentState == ScreenState.BossFight;
    public int CurrentLevel => currentLevel;
    public int LevelScore => levelScore;
    public int TotalScore => totalScore;
    public int UnlockedLevel => unlockedLevel;
    public BossController CurrentBoss => boss;

    public float WorldHalfWidth => gameCamera != null ? gameCamera.orthographicSize * gameCamera.aspect : 8.8f;
    public float WorldTop => gameCamera != null ? gameCamera.orthographicSize : 5f;
    public float WorldBottom => -WorldTop;

    private const int MaxLevels = 5;
    private static readonly int[] ScoreGoals = { 1000, 2000, 3500, 5000, 7000 };
    private static readonly string[] LevelNames =
    {
        "Outer Space", "Asteroid Belt", "Alien Patrol", "Deep Space", "Enemy Stronghold"
    };

    private Camera gameCamera;
    private ScreenState stateBeforePause = ScreenState.Playing;
    private int currentLevel = 1;
    private int unlockedLevel = 1;
    private int levelScore;
    private int totalScore;
    private int levelStartTotalScore;
    private int levelStartHealth = PlayerController.MaxHealth;
    private int levelStartWeapon = 1;
    private int bestScore;
    private float levelElapsed;
    private float enemySpawnTimer;
    private float asteroidSpawnTimer;
    private float pickupSpawnTimer;
    private float notificationRemaining;
    private string notification = "";
    private BossController boss;

    private GUIStyle titleStyle;
    private GUIStyle subtitleStyle;
    private GUIStyle bodyStyle;
    private GUIStyle buttonStyle;
    private GUIStyle smallStyle;

    public static void CreateIfMissing()
    {
        if (Instance != null)
            return;

        SpaceShooterGame existing = FindObjectOfType<SpaceShooterGame>();
        if (existing != null)
        {
            Instance = existing;
            return;
        }

        GameObject root = new GameObject("SpaceShooterGame");
        root.AddComponent<SpaceShooterGame>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject);
        Time.timeScale = 1f;

        unlockedLevel = Mathf.Clamp(PlayerPrefs.GetInt("SpaceShooterUnlockedLevel", 1), 1, MaxLevels);
        bestScore = PlayerPrefs.GetInt("SpaceShooterBestScore", 0);

        SetupCamera();
        CreateStarfield();
    }

    private void OnDestroy()
    {
        if (Instance == this)
        {
            Instance = null;
            Time.timeScale = 1f;
        }
    }

    private void SetupCamera()
    {
        gameCamera = Camera.main;
        if (gameCamera == null)
        {
            GameObject cameraObject = new GameObject("Main Camera");
            cameraObject.tag = "MainCamera";
            gameCamera = cameraObject.AddComponent<Camera>();
        }

        gameCamera.orthographic = true;
        gameCamera.orthographicSize = 5f;
        gameCamera.transform.position = new Vector3(0f, 0f, -10f);
        gameCamera.clearFlags = CameraClearFlags.SolidColor;
        gameCamera.backgroundColor = new Color(0.012f, 0.022f, 0.075f);
    }

    private void CreateStarfield()
    {
        for (int i = 0; i < 105; i++)
        {
            GameObject star = new GameObject("Star");
            star.transform.position = new Vector3(
                Random.Range(-WorldHalfWidth, WorldHalfWidth),
                Random.Range(WorldBottom, WorldTop),
                4f);

            float size = Random.Range(0.025f, 0.075f);
            star.transform.localScale = Vector3.one * size;

            SpriteRenderer renderer = star.AddComponent<SpriteRenderer>();
            Color starColor = Random.value > 0.82f
                ? new Color(0.35f, 0.75f, 1f)
                : new Color(0.72f, 0.83f, 1f);
            renderer.sprite = SpriteFactory.Circle(starColor);
            renderer.sortingOrder = -100;

            StarfieldController controller = star.AddComponent<StarfieldController>();
            controller.Initialize(Random.Range(0.18f, 0.75f), WorldTop);
        }
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Escape))
        {
            if (IsGameplayActive)
                PauseGame();
            else if (CurrentState == ScreenState.Paused)
                ResumeGame();
        }

        if (CurrentState == ScreenState.MainMenu)
            return;

        if (CurrentState == ScreenState.GameOver || CurrentState == ScreenState.Victory || CurrentState == ScreenState.LevelClear)
            return;

        if (CurrentState == ScreenState.Paused)
            return;

        if (!IsGameplayActive)
            return;

        levelElapsed += Time.deltaTime;
        notificationRemaining = Mathf.Max(0f, notificationRemaining - Time.deltaTime);

        if (CurrentState == ScreenState.Playing)
        {
            enemySpawnTimer -= Time.deltaTime;
            if (enemySpawnTimer <= 0f)
            {
                SpawnEnemy();
                enemySpawnTimer = Mathf.Max(0.48f, 1.45f - currentLevel * 0.13f);
            }

            asteroidSpawnTimer -= Time.deltaTime;
            if (asteroidSpawnTimer <= 0f)
            {
                SpawnAsteroid();
                asteroidSpawnTimer = Random.Range(2.1f, 3.5f) - Mathf.Min(0.7f, currentLevel * 0.08f);
            }

            pickupSpawnTimer -= Time.deltaTime;
            if (pickupSpawnTimer <= 0f)
            {
                if (Random.value < 0.72f)
                    SpawnPickup((PickupType)Random.Range(0, 8), new Vector2(Random.Range(-WorldHalfWidth + 0.6f, WorldHalfWidth - 0.6f), Random.Range(-2.5f, 3.3f)));
                pickupSpawnTimer = Random.Range(8f, 12f);
            }
        }
    }

    public Vector3 ClampPlayerPosition(Vector3 position)
    {
        float marginX = Mathf.Min(0.45f, WorldHalfWidth * 0.12f);
        position.x = Mathf.Clamp(position.x, -WorldHalfWidth + marginX, WorldHalfWidth - marginX);
        position.y = Mathf.Clamp(position.y, WorldBottom + 0.55f, WorldTop - 0.55f);
        position.z = 0f;
        return position;
    }

    public static int ScoreGoalForLevel(int level)
    {
        return ScoreGoals[Mathf.Clamp(level, 1, MaxLevels) - 1];
    }

    public static string LevelNameForLevel(int level)
    {
        return LevelNames[Mathf.Clamp(level, 1, MaxLevels) - 1];
    }

    public void StartNewGame(int level)
    {
        Time.timeScale = 1f;
        RemoveTransientObjects();

        if (Player != null)
            Destroy(Player.gameObject);

        Player = null;
        boss = null;
        currentLevel = Mathf.Clamp(level, 1, unlockedLevel);
        totalScore = 0;
        levelScore = 0;
        levelElapsed = 0f;

        CreatePlayer();
        Player.ResetForLevel(PlayerController.MaxHealth, 1);
        BeginLevel();
        Notify("LEVEL " + currentLevel + " — " + LevelNameForLevel(currentLevel));
    }

    private void CreatePlayer()
    {
        GameObject playerObject = new GameObject("Player Ship");
        playerObject.transform.position = new Vector3(0f, WorldBottom + 1.25f, 0f);
        playerObject.transform.localScale = Vector3.one * 0.82f;

        SpriteRenderer renderer = playerObject.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.PlayerShip();
        renderer.sortingOrder = 5;

        Rigidbody2D body = playerObject.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.useFullKinematicContacts = true;
        body.gravityScale = 0f;

        CircleCollider2D collider = playerObject.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.36f;

        Player = playerObject.AddComponent<PlayerController>();
    }

    private void BeginLevel()
    {
        RemoveTransientObjects();
        if (Player != null)
        {
            Player.transform.position = new Vector3(0f, WorldBottom + 1.25f, 0f);
            Player.transform.rotation = Quaternion.identity;
        }

        boss = null;
        levelScore = 0;
        levelElapsed = 0f;
        enemySpawnTimer = 0.65f;
        asteroidSpawnTimer = 1.8f;
        pickupSpawnTimer = 5.5f;
        levelStartTotalScore = totalScore;
        levelStartHealth = Player != null ? Player.Health : PlayerController.MaxHealth;
        levelStartWeapon = Player != null ? Player.WeaponLevel : 1;
        CurrentState = ScreenState.Playing;
        Time.timeScale = 1f;
    }

    public void RestartCurrentLevel()
    {
        if (Player == null)
        {
            StartNewGame(currentLevel);
            return;
        }

        Time.timeScale = 1f;
        totalScore = levelStartTotalScore;
        Player.ResetForLevel(levelStartHealth, levelStartWeapon);
        BeginLevel();
        Notify("RESTART — LEVEL " + currentLevel);
    }

    public void PauseGame()
    {
        if (!IsGameplayActive)
            return;

        stateBeforePause = CurrentState;
        CurrentState = ScreenState.Paused;
        Time.timeScale = 0f;
    }

    public void ResumeGame()
    {
        if (CurrentState != ScreenState.Paused)
            return;

        CurrentState = stateBeforePause;
        Time.timeScale = 1f;
    }

    public void ReturnToMenu()
    {
        Time.timeScale = 1f;
        RemoveTransientObjects();
        if (Player != null)
            Destroy(Player.gameObject);
        Player = null;
        boss = null;
        CurrentState = ScreenState.MainMenu;
        notification = "";
    }

    private void SpawnEnemy()
    {
        GameObject enemyObject = new GameObject("Enemy");
        enemyObject.transform.position = new Vector3(Random.Range(-WorldHalfWidth + 0.5f, WorldHalfWidth - 0.5f), WorldTop + 0.6f, 0f);
        enemyObject.transform.localScale = Vector3.one * Random.Range(0.48f, 0.66f);

        SpriteRenderer renderer = enemyObject.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.EnemyShip();
        renderer.sortingOrder = 4;

        Rigidbody2D body = enemyObject.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.useFullKinematicContacts = true;
        body.gravityScale = 0f;

        CircleCollider2D collider = enemyObject.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.38f;

        EnemyController enemy = enemyObject.AddComponent<EnemyController>();
        enemy.Initialize(currentLevel);
    }

    private void SpawnAsteroid()
    {
        GameObject asteroidObject = new GameObject("Asteroid");
        asteroidObject.transform.position = new Vector3(Random.Range(-WorldHalfWidth + 0.45f, WorldHalfWidth - 0.45f), WorldTop + 0.8f, 0f);
        float size = Random.Range(0.48f, 0.9f);
        asteroidObject.transform.localScale = Vector3.one * size;

        SpriteRenderer renderer = asteroidObject.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.Asteroid();
        renderer.sortingOrder = 2;

        Rigidbody2D body = asteroidObject.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.useFullKinematicContacts = true;
        body.gravityScale = 0f;

        CircleCollider2D collider = asteroidObject.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.42f;

        AsteroidController asteroid = asteroidObject.AddComponent<AsteroidController>();
        asteroid.Initialize(new Vector2(Random.Range(-0.65f, 0.65f), -Random.Range(0.75f, 1.7f)));
    }

    private void SpawnPickup(PickupType type, Vector2 position)
    {
        GameObject pickupObject = new GameObject("Pickup " + type);
        pickupObject.transform.position = position;
        pickupObject.transform.localScale = Vector3.one * 0.55f;

        SpriteRenderer renderer = pickupObject.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.Pickup(type);
        renderer.sortingOrder = 6;

        Rigidbody2D body = pickupObject.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.useFullKinematicContacts = true;
        body.gravityScale = 0f;

        CircleCollider2D collider = pickupObject.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.46f;

        PickupController pickup = pickupObject.AddComponent<PickupController>();
        pickup.Initialize(type, position);
    }

    private void ClearArenaForBoss()
    {
        // Clean up regular enemies, hazards, and projectiles so the Boss fight is focused.
        foreach (EnemyController item in FindObjectsOfType<EnemyController>())
            Destroy(item.gameObject);
        foreach (AsteroidController item in FindObjectsOfType<AsteroidController>())
            Destroy(item.gameObject);
        foreach (BulletController item in FindObjectsOfType<BulletController>())
            Destroy(item.gameObject);
    }

    private void SpawnBoss()
    {
        ClearArenaForBoss();
        GameObject bossObject = new GameObject("Boss Level " + currentLevel);
        bossObject.transform.position = new Vector3(0f, 3.15f, 0f);
        bossObject.transform.localScale = new Vector3(1.8f, 1.35f, 1f);

        SpriteRenderer renderer = bossObject.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.BossShip(currentLevel);
        renderer.sortingOrder = 7;

        Rigidbody2D body = bossObject.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.useFullKinematicContacts = true;
        body.gravityScale = 0f;

        BoxCollider2D collider = bossObject.AddComponent<BoxCollider2D>();
        collider.isTrigger = true;
        collider.size = new Vector2(0.88f, 0.72f);

        boss = bossObject.AddComponent<BossController>();
        boss.Initialize(currentLevel);
        Notify("BOSS INCOMING!");
    }

    public void EnemyDefeated(EnemyController enemy, int points)
    {
        if (!IsGameplayActive)
            return;

        AddScore(points);
        if (Random.value < 0.28f)
        {
            PickupType drop = (PickupType)Random.Range(0, 5);
            SpawnPickup(drop, enemy.transform.position);
        }
    }

    private void AddScore(int points)
    {
        if (CurrentState != ScreenState.Playing)
            return;

        levelScore += points;
        totalScore += points;
        if (levelScore >= ScoreGoalForLevel(currentLevel))
        {
            CurrentState = ScreenState.BossFight;
            SpawnBoss();
        }
    }

    public void BossDefeated(BossController defeatedBoss)
    {
        if (CurrentState != ScreenState.BossFight || boss != defeatedBoss)
            return;

        boss = null;
        levelScore += 1000;
        totalScore += 1000;
        SaveBestScore();

        if (currentLevel >= MaxLevels)
        {
            CurrentState = ScreenState.Victory;
            Time.timeScale = 0f;
            Notify("FINAL BOSS DEFEATED!");
        }
        else
        {
            unlockedLevel = Mathf.Max(unlockedLevel, currentLevel + 1);
            PlayerPrefs.SetInt("SpaceShooterUnlockedLevel", unlockedLevel);
            PlayerPrefs.Save();
            CurrentState = ScreenState.LevelClear;
            Time.timeScale = 0f;
            Notify("BOSS DEFEATED — LEVEL CLEAR");
        }
    }

    public void GameOver()
    {
        if (CurrentState == ScreenState.GameOver || CurrentState == ScreenState.Victory)
            return;

        CurrentState = ScreenState.GameOver;
        Time.timeScale = 0f;
        SaveBestScore();
    }

    private void SaveBestScore()
    {
        if (totalScore > bestScore)
        {
            bestScore = totalScore;
            PlayerPrefs.SetInt("SpaceShooterBestScore", bestScore);
            PlayerPrefs.Save();
        }
    }

    private void RemoveTransientObjects()
    {
        foreach (EnemyController item in FindObjectsOfType<EnemyController>())
            Destroy(item.gameObject);
        foreach (BulletController item in FindObjectsOfType<BulletController>())
            Destroy(item.gameObject);
        foreach (AsteroidController item in FindObjectsOfType<AsteroidController>())
            Destroy(item.gameObject);
        foreach (PickupController item in FindObjectsOfType<PickupController>())
            Destroy(item.gameObject);
        foreach (BossController item in FindObjectsOfType<BossController>())
            Destroy(item.gameObject);
    }

    public void Notify(string message)
    {
        notification = message;
        notificationRemaining = 2.6f;
    }

    private void OnGUI()
    {
        EnsureStyles();

        if (CurrentState == ScreenState.MainMenu)
        {
            DrawMainMenu();
            return;
        }

        if (CurrentState == ScreenState.Playing || CurrentState == ScreenState.BossFight || CurrentState == ScreenState.Paused)
            DrawHud();

        switch (CurrentState)
        {
            case ScreenState.Paused: DrawPauseMenu(); break;
            case ScreenState.LevelClear: DrawLevelClear(); break;
            case ScreenState.GameOver: DrawGameOver(); break;
            case ScreenState.Victory: DrawVictory(); break;
        }

        if (notificationRemaining > 0f && IsGameplayActive)
        {
            Rect notifyRect = new Rect(Screen.width * 0.5f - 230f, 80f, 460f, 42f);
            GUI.Label(notifyRect, notification, subtitleStyle);
        }
    }

    private void EnsureStyles()
    {
        if (titleStyle != null)
            return;

        titleStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = 32,
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter
        };
        titleStyle.normal.textColor = new Color(0.35f, 0.90f, 1f);

        subtitleStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = 19,
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter,
            wordWrap = true
        };
        subtitleStyle.normal.textColor = Color.white;

        bodyStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = 15,
            alignment = TextAnchor.MiddleCenter,
            wordWrap = true
        };
        bodyStyle.normal.textColor = new Color(0.82f, 0.88f, 1f);

        smallStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = 13,
            alignment = TextAnchor.MiddleCenter,
            wordWrap = true
        };
        smallStyle.normal.textColor = new Color(0.74f, 0.82f, 0.95f);

        buttonStyle = new GUIStyle(GUI.skin.button)
        {
            fontSize = 17,
            fontStyle = FontStyle.Bold
        };
    }

    private void DrawMainMenu()
    {
        DrawScreenTint();
        Rect panel = CenteredPanel(590f, 535f);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x + 20f, panel.y + 22f, panel.width - 40f, 58f), "SPACE SHOOTER", titleStyle);
        GUI.Label(new Rect(panel.x + 30f, panel.y + 80f, panel.width - 60f, 36f), "AUTO-FIRE  •  SURVIVE  •  DEFEAT EVERY BOSS", smallStyle);

        if (GUI.Button(new Rect(panel.x + 120f, panel.y + 128f, panel.width - 240f, 48f), "NEW GAME — LEVEL 1", buttonStyle))
            StartNewGame(1);

        GUI.Label(new Rect(panel.x + 35f, panel.y + 190f, panel.width - 70f, 30f), "SELECT AN UNLOCKED LEVEL", subtitleStyle);
        float buttonWidth = 88f;
        float spacing = 10f;
        float totalWidth = buttonWidth * MaxLevels + spacing * (MaxLevels - 1);
        float startX = panel.x + (panel.width - totalWidth) * 0.5f;
        for (int i = 1; i <= MaxLevels; i++)
        {
            bool enabled = i <= unlockedLevel;
            GUI.enabled = enabled;
            string label = enabled ? "LEVEL " + i : "LOCKED";
            if (GUI.Button(new Rect(startX + (i - 1) * (buttonWidth + spacing), panel.y + 225f, buttonWidth, 42f), label, buttonStyle))
                StartNewGame(i);
        }
        GUI.enabled = true;

        GUI.Label(new Rect(panel.x + 35f, panel.y + 284f, panel.width - 70f, 26f),
            "Best score: " + bestScore + "     |     Highest unlocked: " + unlockedLevel + "/" + MaxLevels, bodyStyle);
        GUI.Label(new Rect(panel.x + 35f, panel.y + 328f, panel.width - 70f, 86f),
            "WASD / Arrow keys: move\nMouse position: aim (the ship auto-fires)\nEsc: pause or resume", bodyStyle);
        GUI.Label(new Rect(panel.x + 35f, panel.y + 433f, panel.width - 70f, 56f),
            "Every level ends with a Boss. Reach the score goal, defeat that Boss, and unlock the next level.", smallStyle);
    }

    private void DrawHud()
    {
        Rect panel = new Rect(14f, 14f, 330f, 176f);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x + 12f, panel.y + 7f, 300f, 25f),
            "LEVEL " + currentLevel + " — " + LevelNameForLevel(currentLevel), subtitleStyle);

        int health = Player != null ? Player.Health : 0;
        Rect healthBar = new Rect(panel.x + 16f, panel.y + 40f, 285f, 15f);
        GUI.Box(healthBar, GUIContent.none);
        Color oldColor = GUI.color;
        GUI.color = health > 30 ? new Color(0.16f, 0.88f, 0.42f) : new Color(1f, 0.23f, 0.24f);
        GUI.DrawTexture(new Rect(healthBar.x + 2f, healthBar.y + 2f, (healthBar.width - 4f) * health / PlayerController.MaxHealth, healthBar.height - 4f), Texture2D.whiteTexture);
        GUI.color = oldColor;

        GUI.Label(new Rect(panel.x + 12f, panel.y + 59f, 300f, 22f),
            "HP: " + health + "/100     Weapon: " + (Player != null ? Player.WeaponLevel : 1) + "/3", bodyStyle);
        GUI.Label(new Rect(panel.x + 12f, panel.y + 83f, 300f, 22f),
            "Stage score: " + levelScore + " / " + ScoreGoalForLevel(currentLevel), bodyStyle);
        GUI.Label(new Rect(panel.x + 12f, panel.y + 106f, 300f, 22f), "Total score: " + totalScore, bodyStyle);
        string effects = Player != null ? Player.ActiveEffectsSummary() : "None";
        GUI.Label(new Rect(panel.x + 12f, panel.y + 130f, 308f, 35f), "Effects: " + effects, smallStyle);

        if (GUI.Button(new Rect(Screen.width - 126f, 14f, 112f, 38f), "Ⅱ  PAUSE", buttonStyle))
            PauseGame();

        if (CurrentState == ScreenState.BossFight && boss != null)
        {
            Rect bossPanel = new Rect(Screen.width * 0.5f - 210f, 16f, 420f, 56f);
            GUI.Box(bossPanel, GUIContent.none);
            GUI.Label(new Rect(bossPanel.x + 8f, bossPanel.y + 2f, bossPanel.width - 16f, 22f), "BOSS — LEVEL " + currentLevel, subtitleStyle);
            Rect bossBar = new Rect(bossPanel.x + 18f, bossPanel.y + 29f, bossPanel.width - 36f, 15f);
            GUI.Box(bossBar, GUIContent.none);
            GUI.color = new Color(1f, 0.20f, 0.32f);
            float ratio = boss.MaxHealth <= 0f ? 0f : boss.CurrentHealth / boss.MaxHealth;
            GUI.DrawTexture(new Rect(bossBar.x + 2f, bossBar.y + 2f, (bossBar.width - 4f) * ratio, bossBar.height - 4f), Texture2D.whiteTexture);
            GUI.color = oldColor;
        }
    }

    private void DrawPauseMenu()
    {
        DrawScreenTint();
        Rect panel = CenteredPanel(450f, 355f);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x + 20f, panel.y + 25f, panel.width - 40f, 55f), "PAUSED", titleStyle);
        GUI.Label(new Rect(panel.x + 30f, panel.y + 82f, panel.width - 60f, 32f),
            stateBeforePause == ScreenState.BossFight ? "Boss fight paused — your progress is safe." : "The game world and buff timers are frozen.", bodyStyle);

        if (GUI.Button(new Rect(panel.x + 70f, panel.y + 132f, panel.width - 140f, 44f), "RESUME", buttonStyle))
            ResumeGame();
        if (GUI.Button(new Rect(panel.x + 70f, panel.y + 187f, panel.width - 140f, 44f), "RESTART LEVEL", buttonStyle))
            RestartCurrentLevel();
        if (GUI.Button(new Rect(panel.x + 70f, panel.y + 242f, panel.width - 140f, 44f), "MAIN MENU", buttonStyle))
            ReturnToMenu();
        GUI.Label(new Rect(panel.x + 28f, panel.y + 302f, panel.width - 56f, 28f), "Shortcut: Esc", smallStyle);
    }

    private void DrawLevelClear()
    {
        DrawScreenTint();
        Rect panel = CenteredPanel(500f, 355f);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x + 20f, panel.y + 24f, panel.width - 40f, 55f), "BOSS DEFEATED!", titleStyle);
        GUI.Label(new Rect(panel.x + 28f, panel.y + 89f, panel.width - 56f, 34f),
            "LEVEL " + currentLevel + " COMPLETE", subtitleStyle);
        GUI.Label(new Rect(panel.x + 30f, panel.y + 132f, panel.width - 60f, 48f),
            "Stage score: " + levelScore + "     Total score: " + totalScore + "\nLevel " + (currentLevel + 1) + " is now unlocked.", bodyStyle);
        if (GUI.Button(new Rect(panel.x + 80f, panel.y + 206f, panel.width - 160f, 46f), "NEXT LEVEL  →", buttonStyle))
            GoToNextLevel();
        if (GUI.Button(new Rect(panel.x + 80f, panel.y + 264f, panel.width - 160f, 40f), "MAIN MENU", buttonStyle))
            ReturnToMenu();
    }

    private void DrawGameOver()
    {
        DrawScreenTint();
        Rect panel = CenteredPanel(480f, 350f);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x + 20f, panel.y + 24f, panel.width - 40f, 55f), "GAME OVER", titleStyle);
        GUI.Label(new Rect(panel.x + 30f, panel.y + 88f, panel.width - 60f, 56f),
            "You were defeated on Level " + currentLevel + ".\nTotal score: " + totalScore + "    Best: " + bestScore, bodyStyle);
        if (GUI.Button(new Rect(panel.x + 75f, panel.y + 166f, panel.width - 150f, 46f), "RETRY LEVEL", buttonStyle))
            RestartCurrentLevel();
        if (GUI.Button(new Rect(panel.x + 75f, panel.y + 224f, panel.width - 150f, 42f), "MAIN MENU", buttonStyle))
            ReturnToMenu();
        GUI.Label(new Rect(panel.x + 25f, panel.y + 294f, panel.width - 50f, 26f), "Unlocked progress is saved.", smallStyle);
    }

    private void DrawVictory()
    {
        DrawScreenTint();
        Rect panel = CenteredPanel(500f, 365f);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x + 20f, panel.y + 25f, panel.width - 40f, 55f), "GALAXY SAVED!", titleStyle);
        GUI.Label(new Rect(panel.x + 30f, panel.y + 95f, panel.width - 60f, 62f),
            "You defeated every Boss and cleared all " + MaxLevels + " levels.\nTotal score: " + totalScore + "    Best: " + bestScore, bodyStyle);
        if (GUI.Button(new Rect(panel.x + 75f, panel.y + 188f, panel.width - 150f, 46f), "PLAY AGAIN", buttonStyle))
            StartNewGame(1);
        if (GUI.Button(new Rect(panel.x + 75f, panel.y + 246f, panel.width - 150f, 42f), "MAIN MENU", buttonStyle))
            ReturnToMenu();
    }

    private void DrawScreenTint()
    {
        Color old = GUI.color;
        GUI.color = new Color(0.01f, 0.02f, 0.07f, 0.78f);
        GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.whiteTexture);
        GUI.color = old;
    }

    private Rect CenteredPanel(float width, float height)
    {
        width = Mathf.Min(width, Screen.width - 24f);
        height = Mathf.Min(height, Screen.height - 24f);
        return new Rect((Screen.width - width) * 0.5f, (Screen.height - height) * 0.5f, width, height);
    }

    private void GoToNextLevel()
    {
        if (CurrentState != ScreenState.LevelClear || currentLevel >= MaxLevels)
            return;

        Time.timeScale = 1f;
        currentLevel++;
        if (Player != null)
        {
            Player.Heal(30);
            // Clear temporary effects while preserving the upgraded weapon and healed HP.
            Player.ResetForLevel(Player.Health, Player.WeaponLevel);
        }
        BeginLevel();
        Notify("LEVEL " + currentLevel + " — " + LevelNameForLevel(currentLevel));
    }
}
